import { test, expect } from '@playwright/test';

test.describe('3D View Toggle', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
  });

  test('3D button activates Three.js renderer', async ({ page }) => {
    // Click 3D button
    await page.click('#view-3d-btn');

    // Wait for Three.js canvas to appear inside canvas-container
    // Three.js creates a <canvas> element inside the container
    await expect(page.locator('#view-3d-btn')).toHaveClass(/active/, { timeout: 5_000 });

    // Verify renderer3d debug surface reports active
    const isActive = await page.evaluate(() => {
      return (window as any).__renderer3d?.isActive === true;
    });
    expect(isActive).toBe(true);
  });

  test('pressing 3 key toggles 3D view', async ({ page }) => {
    // Focus body to ensure key works
    await page.click('#pcb-canvas');
    await page.keyboard.press('3');

    await expect(page.locator('#view-3d-btn')).toHaveClass(/active/, { timeout: 5_000 });

    const isActive = await page.evaluate(() => {
      return (window as any).__renderer3d?.isActive === true;
    });
    expect(isActive).toBe(true);
  });

  test('toggling back to 2D removes 3D and restores canvas', async ({ page }) => {
    // Activate 3D
    await page.click('#view-3d-btn');
    await expect(page.locator('#view-3d-btn')).toHaveClass(/active/, { timeout: 5_000 });

    // 2D canvas should be hidden
    await expect(page.locator('#pcb-canvas')).toBeHidden();

    // Toggle back to 2D
    await page.click('#view-3d-btn');

    // Button should lose active class
    await expect(page.locator('#view-3d-btn')).not.toHaveClass(/active/);

    // 2D canvas should be visible again
    await expect(page.locator('#pcb-canvas')).toBeVisible();

    // renderer3d should be disposed
    const isActive = await page.evaluate(() => {
      return (window as any).__renderer3d?.isActive ?? false;
    });
    expect(isActive).toBe(false);
  });
});

  private buildComponents(components: ComponentInfo[], topGroup: THREE.Group): void {
    let smdCount = 0;
    let thtCount = 0;

    const icMat = new THREE.MeshStandardMaterial({
      color: 0x404040,
      metalness: 0.3,
      roughness: 0.5,
    });

    const passiveMat = new THREE.MeshStandardMaterial({
      color: 0xc2a366,
      metalness: 0.1,
      roughness: 0.6,
    });

    for (const comp of components) {
      let bodyW = comp.body_width_nm * NM_TO_MM;
      let bodyH = comp.body_height_nm * NM_TO_MM;

      // Fallback: compute bounding box from pads if body dimensions missing
      if (bodyW <= 0 || bodyH <= 0) {
        if (comp.pads.length > 0) {
          let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
          for (const pad of comp.pads) {
            const hw = (pad.width_nm * NM_TO_MM) / 2;
            const hh = (pad.height_nm * NM_TO_MM) / 2;
            const px = pad.x_nm * NM_TO_MM;
            const py = pad.y_nm * NM_TO_MM;
            minX = Math.min(minX, px - hw);
            minY = Math.min(minY, py - hh);
            maxX = Math.max(maxX, px + hw);
            maxY = Math.max(maxY, py + hh);
          }
          bodyW = maxX - minX;
          bodyH = maxY - minY;
          console.log(`[3D] Warning: component ${comp.refdes} has no body dimensions, using pad bbox fallback`);
        } else {
          continue; // No body info at all — skip
        }
      }

      // Determine if THT (any pad with drill) or SMD
      const isTHT = comp.pads.some(p => p.drill_nm != null && p.drill_nm > 0);
      const compHeight = isTHT ? THT_HEIGHT_MM : SMD_HEIGHT_MM;

      if (isTHT) thtCount++;
      else smdCount++;

      // Material: IC (U/IC prefix) = dark gray, passive (R/C/L) = tan
      const prefix = comp.refdes.replace(/[0-9]+$/, '').toUpperCase();
      const isIC = prefix === 'U' || prefix === 'IC';
      const mat = isIC ? icMat : passiveMat;

      // Create box at component position
      const geo = new THREE.BoxGeometry(bodyW, bodyH, compHeight);
      const mesh = new THREE.Mesh(geo, mat);

